"""Complete Linux bitops header, including storage, rotations, sign and CAS macros."""
def register(topic,q,detail):
 def lesson(title,symbol,why,principle,use,reading,qa,cards):
  topic(title,'라이브러리·알고리즘','include/linux/bitops.h',symbol,why,principle,use,reading,*(q(*x) for x in qa),details=[detail(*x) for x in cards])
 lesson('비트 저장 크기·sizeof와올림나눗셈','BITS_TO_LONGS',
  '비트 개수에서 실제 배열 원소 개수를 구하고 byte·word·bit 단위를 구분합니다.',
  'BITS_PER_TYPE(type)는sizeof(type)에8을 곱합니다. BITS_TO_LONGS/U64/U32/BYTES는 필요한 bit 수를 각원소폭으로올림나눗셈합니다.64bit long에서65bit는long두개가필요합니다. BITS_TO_BYTES(9)는2byte입니다. BYTES_TO_BITS는byte수를8배하며변환방향이반대입니다.',
  '비트맵 배열을 준비할 때 저장 타입과 bit 개수를 함께 확인합니다. 배열 원소 개수와 할당 byte 길이를 따로 계산합니다. sizeof(long)은실제target ABI에따르므로모든환경에서64라고고정하지않습니다.',
  '다섯크기macro와BYTES_TO_BITS,실제sizeof를읽으세요.',
  [('64bit long에65bit를담으려면원소몇개가필요한가?','2개다','65개다','각long이64bit를담습니다.남은1bit를위한추가원소가필요하며bit수와원소수를구분합니다.'),('BITS_TO_BYTES(9)의결과는?','2다','9다','byte당8bit입니다.9bit는1byte를넘으므로올림해2byte가필요합니다.')],
  [('검사','0..100000bit의long/u64/u32/byte 원소 개수를몫+나머지유무기준과대조했습니다.'),('포함 경로','bitops.h는bits.h와typecheck.h, UAPI kernel.h를포함합니다.올림macro는UAPI const.h정의로연결됩니다.')])
 lesson('큰 비트 수 계산·올림식도overflow를검사하지않는다','BITS_TO_LONGS',
  '편리한 크기 macro가 매우 큰 입력까지 안전한 할당을 보장하는지 확인합니다.',
  '올림식은(n+d-1)/d입니다.unsigned n이최대값근처이면더하는중간값이wrap돼작은결과가될 수 있습니다.실제long64 fixture에서BITS_TO_LONGS(~0UL)은0입니다.그래서크기macro결과가작다고입력에필요한저장공간도작다는뜻은아닙니다. byte 길이계산의곱셈도별도overflow검사가필요합니다.',
  '외부 입력의 bit 개수를 제한하고 덧셈·곱셈 범위를 확인한 뒤 할당합니다. 큰 값에서는 n/d+(n%d!=0) 같은 분해식의전제와후속곱셈도검토합니다.단순macro를안전한할당validator로설명하지않습니다.',
  '__KERNEL_DIV_ROUND_UP의덧셈순서와큰unsigned반례를읽으세요.',
  [('BITS_TO_LONGS가모든입력의overflow를오류로반환하는가?','아니며unsigned중간덧셈이wrap될수있다','너무큰입력은항상errno를반환한다','원문은산술macro입니다.오류반환이나포화처리가없으며실제최대 unsigned반례도검사했습니다.'),('외부bit수의배열할당에서추가로필요한확인은?','입력범위와크기산술의overflow조건이다','macro결과가있으면아무추가확인이필요없다','원소수계산과byte 길이곱셈의중간값을확인해야합니다.작게wrap된할당으로큰입력을처리하지않습니다.')],
  [('반례','이검사는정의된unsigned wrap입니다. signed overflow를실행하거나허용한다는의미가아닙니다.'),('단위','원소수에sizeof원소를곱해byte 길이를구하는단계도범위 검사가필요합니다.')])
 lesson('64비트 rotate·양쪽shift를63으로mask','rol64',
  '끝으로 나간bit를 반대쪽으로 다시 넣는 회전을 일반 shift와 구분합니다.',
  'rol64는word<<(shift&63)과word>>((-shift)&63)을OR합니다. ror64는방향을바꿉니다. unsigned shift의음수는modulo값이며63mask가반대쪽이동량을0..63으로만듭니다. shift0일때두shift모두0이어서폭만큼shift하는오류를피합니다. shift64는0회전과같고큰입력도64로나눈나머지회전입니다.',
  '암호나해시원문에서rotate와논리shift를구분해읽습니다.최상위 bit가최하위로돌아오는one-bit예를그립니다.여기서는64bit unsigned값의순환위치변환이며보수NOT이나bit reversal이아닙니다.',
  '두mask·unsigned -shift·OR와ror64역방향을읽으세요.',
  [('64bit에서가장 높은bit하나를왼쪽1회전하면?','가장 낮은 bit로돌아온다','반드시사라져0이된다','rotate는빠져나간bit를반대끝으로이어붙입니다.단순left shift와다릅니다.'),('rol64의shift64는?','shift0과같은결과다','64bit밖shift를그대로실행한다','두이동량에63mask를사용합니다.64의나머지는0이며유효한 shift만수행합니다.')],
  [('검사','0·1·경계·폭·폭+1·UINT_MAX회전량을독립bit위치loop와대조했습니다.'),('폭','고정64bit helper입니다. unsigned long의폭을추측한machineword회전으로바꾸어설명하지않습니다.')])
 lesson('32비트 rotate·잘린것을반대끝으로합성','ror32',
  '32비트 회전의폭과 이동량 정규화를 직접 계산해 배웁니다.',
  'rol32/ror32는unsigned32 word에31mask를사용합니다. ror32(1,1)은0x80000000입니다.논리right shift로사라질낮은 bit가왼쪽합성식에서높은위치로돌아옵니다.회전량을32로나눈나머지로맞추므로shift32는identity입니다.64bit입력을넘겨도함수의word타입에맞게32bit로받습니다.',
  '32bit입력과예상결과를명시한뒤역회전으로복원되는지확인합니다.표현폭이64인자료에32bit helper를사용해상위 bit까지변환한다고가정하지 않습니다.',
  'ror32의rightshift와보완leftshift·31mask를읽으세요.',
  [('ror32(1,1)의결과는?','0x80000000이다','0이다','bit0이반대끝bit31로돌아갑니다.논리rightshift만한결과와다릅니다.'),('32bit회전에shift33을넣으면?','shift1과같다','항상입력33개bit를지운다','31mask가32의나머지를고릅니다.이동량정규화와데이터삭제를혼동하지않습니다.')],
  [('검사','native32 unsigned값의좌우회전을독립 bit loop와비교했습니다.'),('기술 차이','rotate,byteswap,bitreverse는서로 다른위치변환입니다.하나의helper로모두대체하지않습니다.')])
 lesson('8·16비트 rotate·좁은반환과정수 승격','rol16',
  '작은폭 helper에서도 중간 표현과 반환 폭을 확인하는 방법을 배웁니다.',
  'rol16/ror16은15mask,rol8/ror8은7mask로회전량을맞춥니다.좁은unsigned입력은C정수 승격으로int계산이될수있고최종u16/u8반환에서폭에맞춥니다.원문의유효shift와native int32문맥에서이중간값을확인해야합니다. helper이름만보고모든중간 계산이좁은타입이라고가정하지 않습니다.',
  '8bit0x80의왼쪽1회전이0x01임을그립니다.실제 입력 폭과shift mask를확인합니다. 다른compiler/type문맥에이식할때중간shift폭까지검토합니다.',
  'rol/ror8과16전체네함수의mask·입력·반환타입을읽으세요.',
  [('8bit0x80을왼쪽1회전한결과는?','0x01이다','0x100이라는9bit결과를그대로반환한다','결과는8bit순환값입니다.최상위 bit가낮은끝으로돌아옵니다.'),('u8/u16인자가모든중간 연산타입까지고정하는가?','아니며C의정수 승격을확인한다','작은반환형이모든연산을자동으로8bit로한다','연산시타입과최종반환 폭은다를수있습니다.원문의shift범위와compiler타입을함께읽습니다.')],
  [('검사','GCCnative64/int32문맥에서전체네함수의경계회전량을검사했습니다.'),('입력','폭이큰값을전달하면먼저해당word타입으로변환됩니다.잘린상위 bit까지보존하지않습니다.')])
 lesson('sign_extend32·지정한 bit를부호 bit로해석','sign_extend32',
  '작은signed필드의부호를넓은정수로전파하는 기술을 배웁니다.',
  'sign_extend32는index를0기반부호 bit위치로받습니다.31-index만큼unsignedvalue를올려그bit를bit31로옮기고signed32로cast한뒤같은만큼산술rightshift합니다.그위의불필요한입력bit는unsignedleftshift에서사라집니다.네bit값1101인13을index3으로해석하면-3입니다.',
  '장치나파일의작은signed필드를먼저추출한뒤마지막bit위치에맞는index를사용합니다.0<=index<32를지킵니다. byte순서변환과부호 해석이필요하면각단계를정확히구분합니다.',
  '31-index·unsigned leftshift·signedcast·rightshift를읽으세요.',
  [('sign_extend32(13,3)의숫자는?','-3이다','항상양수13이다','네bit1101의bit3은부호 bit입니다.2의 보수네bit표현을32bit signed로부호 확장합니다.'),('index는필드폭자체인가?','아니며0기반부호 bit위치다','폭4이면index도반드시4다','네bit필드의가장 높은위치는3입니다.원문의0기반index계약을지킵니다.')],
  [('compiler','signedcast와negative rightshift는GCCtarget의2의 보수·산술shift문맥으로검사했습니다.모든ISO C구현의동일 결과증거는아닙니다.'),('검사','32개의유효index를난수입력에서독립bitmask기준과대조했습니다.범위 밖index는실행하지않습니다.')])
 lesson('sign_extend64·63번부호 bit까지다루기','sign_extend64',
  '넓은signed필드에서도 같은원리를 적용하고유효한index범위를확인합니다.',
  'sign_extend64는63-index를사용해지정bit를bit63으로옮기고signed64의산술rightshift로돌려놓습니다. index63이면shift0으로전체64bit를signed형식으로해석합니다. index0은한 bit signed필드이며값1은-1입니다.입력은unsigned64이고부호 해석은이helper의별도단계입니다.',
  '64bit필드폭과부호위치를데이터정의에서확인합니다.0<=index<64를지키고8bit shift변수에저장된다는이유로잘못된index가검증된다고가정하지 않습니다.',
  '63-index·u8 shift변수·s64 cast·rightshift를읽으세요.',
  [('한 bit signed필드값1을index0으로확장하면?','-1이다','양수1만가능하다','한 bit 2의 보수signed값에서그bit는부호 bit입니다.모든상위 bit로1을전파합니다.'),('index64는유효한계약인가?','아니며0..63범위다','u8 shift변수가자동으로입력을정상화한다','shift변수의좁은타입은입력검증을제공하지않습니다.함수의명시index전제를지켜야 합니다.')],
  [('검사','64개유효index의결과bit표현을독립mask·부호전파reference와비교했습니다.'),('값과표현','음수결과를unsigned로다시cast한 bit표현과참조를비교합니다.경계값을signed덧셈overflow로계산하지않습니다.')])
 lesson('bitmask order와count order·같은숫자에다른목적','get_bitmask_order',
  '비슷한 order 이름이 서로 다른 계산 목적과 결과를 가진다는 점을 배웁니다.',
  'get_bitmask_order는fls(count)를반환해가장 높은1위치를1기반으로표현합니다. get_count_order는count0에-1,그외에는fls(count-1)로필요한2의거듭제곱ceil지수를구합니다. count1은bitmaskorder1,countorder0이고count8은각각4와3입니다.목적이달라두함수를자동으로대체하면안됩니다.',
  '비트폭정보가필요한지개수를담는2의거듭제곱크기가필요한지먼저정합니다.0·1·정확한거듭제곱·그다음숫자를표로검산합니다.',
  'fls(count)와zero검사후fls(--count)를대조하세요.',
  [('count8의bitmaskorder와countorder는?','각각4와3이다','둘다항상3이다','fls(8)는bit3의1기반위치4입니다.개수8을담는2의거듭제곱지수는3입니다.'),('count0에서두helper가같은값을반환하는가?','아니며bitmaskorder0,countorder-1이다','두함수모두자동으로1을반환한다','원문의zero조건과fls(0)의계약을각각읽어야 합니다.비슷한이름이같은의미를보장하지않습니다.')],
  [('검사','0..100000의숫자를독립나눗셈기준으로검산했습니다.'),('오류 전파','countorder의-1을unsigned크기로무조건cast해사용하지 않습니다.0입력의특별결과를먼저처리합니다.')])
 lesson('long형count order·sizeof에맞춰fls폭선택','get_count_order_long',
  'machine word폭을따라가는helper의분기와ceil지수계산을배웁니다.',
  'fls_long은sizeof(long)==4이면fls,아니면fls64를선택합니다. get_count_order_long은0에-1을돌려주고그외에는fls_long(--l)을int로돌려줍니다.고정32bit get_count_order와달리long입력 폭을다룹니다.호스트에서매크로를하나바꿔도sizeof(long)의ABI폭은자동으로바뀌지않습니다.',
  '실제unsigned long값의배열크기또는order계산에사용합니다. 고정 폭외부형식값을machineword로무조건축소하지않습니다.현재compiler의sizeof와함수의분기를함께확인합니다.',
  'fls_long의sizeof분기와longzero·감소·fls를읽으세요.',
  [('long폭에따른fls_long분기는무엇을검사하는가?','실제sizeof(long)이다','모든플랫폼에서항상32bit라고가정한다','함수는compiler의자료형크기를사용합니다.매크로선택과실제ABI를구분합니다.'),('get_count_order_long(1)의결과는?','0이다','1이다','count1을먼저0으로줄인뒤fls_long(0)을얻습니다.필요한2의거듭제곱은2의0승입니다.')],
  [('검사','현재native long64문맥에서독립ceilorder기준과비교했습니다.'),('표현','반환형int는zero의-1을표현합니다.unsigned컨테이너에넣기전에입력의특별결과를처리합니다.')])
 lesson('hweight_long·폭선택과실제popcount의역할','hweight_long',
  '설정bit 개수와bit위치를구하는함수가다르다는점을배웁니다.',
  'hweight_long은sizeof(word)==4이면hweight32,아니면hweight64를선택합니다.결과는1bit의총개수이고가장 높은bit위치가아닙니다.0x80000001은1bit가두개라결과2입니다.헤더의__sw_hweight8/16/32/64선언은다른 구현파일의software알고리즘과연결되며public hweight경로는compiler 상수또는arch선택을가질 수 있습니다.',
  '비트맵원소의사용개수를셀때popcount를사용합니다.최고위치나최하위위치는다른helper로구합니다.이fixture에서사용한software구현검사를모든CPU의popcount명령실행으로기록하지않습니다.',
  'sizeof분기와hweight호출·software선언을연결하세요.',
  [('hweight_long(0x80000001)의결과는?','2다','32다','켜진 bit의개수는두개입니다.가장 높은bit의1기반위치32와다른계산입니다.'),('software hweight검사가모든arch의CPU popcount명령도실행했다는뜻인가?','아니며선택된구현증거를구분한다','함수 이름이같으면모든명령이실행된다','fixture는원본software본문을사용합니다.다른arch명령경로의실행검증을대신하지않습니다.')],
  [('연결','이미작성한hweight알고리즘수업과const_hweight선택헤더로이어집니다.'),('검사','각 bit를 따로 센 독립 기준으로 1만 입력의 long helper 결과를 대조했습니다.')])
 lesson('__ffs64·0기반최하위 1과32bit분할','__ffs64',
  '64bit최하위 1위치를word폭에따라구하는원리를배웁니다.',
  '__ffs64는word가nonzero라는전제가있습니다. BITS_PER_LONG64에서는__ffs와같습니다.32분기는낮은u32가0이면높은u32의__ffs에32를더하고,아니면낮은쪽의최하위 1을찾습니다.예를들어bit40만켜졌으면높은절반의위치8에32를더해40입니다.결과는0기반이며zero의결과는정의하지않습니다.',
  '호출전에word!=0을확인합니다.ffs의1기반반환과__ffs의0기반반환을구분합니다.추가 fixture는 long64 호스트에서32조건분기와64분기를 각각 검사했습니다.32분기 산술 검사를 실제 native32 ABI 실행으로 기록하지 않습니다.',
  'nonzero주석·32분기낮은절반검사·높은절반+32·64경로를읽으세요.',
  [('bit40만켜진64bit word의__ffs64결과는?','40이다','41이다','이helper는0기반최하위 1위치를반환합니다.1기반ffs류와구분합니다.'),('word0을무조건호출해64 sentinel을기대해도되는가?','아니며nonzero전제다','모든zero는자동으로64를돌려준다','원문은zero결과를정의하지않습니다.fns의별도sentinel계약과혼동하지않습니다.')],
  [('범위','헤더는32와64이외BITS_PER_LONG에preprocessor error를냅니다.임의word폭을자동지원한다고가정하지 않습니다.'),('검사','32/64 선택 분기 각각100,064개 입력을 독립 lowest-bit 기준과 비교했습니다.32는 long64 호스트의 조건 경로입니다.')])
 lesson('fns·0번째1bit부터하나씩제거하며찾기','fns',
  'n번째켜진 bit를찾는알고리즘과없을때의sentinel을배웁니다.',
  'fns는word&=word-1로그가장 낮은1bit를하나씩지웁니다. n은0기반rank라n0은처음최하위 1을선택합니다. n개를지운뒤word가남으면__ffs로위치를얻고없으면BITS_PER_LONG을반환합니다. word0도sentinel입니다.반환64를bit63같은유효위치로오해하면안됩니다.',
  '켜진 bit의순서중특정rank를선택할때사용합니다.반환값이word폭보다작은지확인한뒤shift나인덱스로사용합니다.n이bit위치자체가아니라켜진 bit의순번임을구분합니다.',
  'word-1 AND·n--·__ffs와폭sentinel을읽으세요.',
  [('word0b10110의rank1이선택하는위치는?','bit2다','bit1이다','켜진위치는1,2,4입니다.rank0은1,rank1은2이며순번은0기반입니다.'),('word에해당rank의1bit가없으면?','BITS_PER_LONG sentinel을반환한다','항상마지막bit를자동선택한다','원문은word가0이면폭sentinel을반환합니다.이를유효bit위치로사용하기전에검사합니다.')],
  [('검사','1만 word의 rank0..64를 직접 bit 위치 순회 기준과 대조했습니다.'),('복잡도','지우는횟수는찾는rank와켜진 bit수에따릅니다.일반적인상수시간전체검색이라고설명하지않습니다.')])
 lesson('non-atomic bitop선택·상수 경로가NULL검사는아니다','bitop',
  'compiler 상수일때generic C경로를선택하는최적화와안전조건을구분합니다.',
  'bitop은nr,addr의nonNULL여부와가리키는word가compiler 상수로판단되면const##op를선택하고그외에는op를호출합니다. uintptr_t cast는항상참주소식의경고를줄이는문맥입니다.조건에nonNULL이있어도NULL을전체호출에서거절하는validator가아닙니다.비상수또는NULL조건은일반경로로넘어갈수있고유효 포인터전제는여전히필요합니다.',
  'public __set/clear/change와test계열에서선택되는구현을따라갑니다.compiler최적화조건을runtime주소검증으로해석하지않습니다.유효 bitmap과범위 안nr를준비합니다.',
  '세상수판단·nonNULL조건·const##op와op삼항을읽으세요.',
  [('bitop조건에NULL검사가있으므로NULL호출이자동으로안전한가?','아니며일반경로의유효 포인터전제가남는다','NULL이면항상접근없이성공 반환한다','조건은상수 경로선택용입니다.전체API의주소검증이나에러반환이아닙니다.'),('compiler 상수 경로선택이non-atomic갱신을atomic으로바꾸는가?','아니며해당API의동시성 계약을유지한다','상수이면자동으로원자적 RMW가된다','최적화와원자성은다른문제입니다.원문의__접두갱신계약을따로읽습니다.')],
  [('포함 순서','generic non-atomic정의를먼저포함하고asm/bitops.h로arch경로를연결합니다.재정의와이름선택을함께읽습니다.'),('검사 범위','fixture는실제generic경로와non-instrumentedalias를사용합니다.모든arch asm이나instrumentation실행검사는아닙니다.')])
 lesson('bitop prototype 검사·네이름계층의타입일치','__check_bitop_pr',
  '비슷한함수 이름들을같은signature로연결하는빌드검사기술을배웁니다.',
  '__check_bitop_pr는arch_name,generic_name,const_name,_name의타입이__same_type으로같은지static_assert합니다. __set/clear/change와test-and세종, test_bit와test_bit_acquire의여덟계약을 확인합니다.이검사는반환형·인자타입연결의검사이며메모리ordering이나각 구현의수학적동치를증명하지않습니다.',
  '새arch wrapper를읽을때prototype과volatile/const포인터수식까지확인합니다.타입 검사통과후에도원자성·ordering·실제결과를별도로검토합니다.헬퍼macro는사용뒤undef됩니다.',
  'static_assert·네계층__same_type·여덟호출과undef를읽으세요.',
  [('prototype 검사통과가모든구현의ordering동치도증명하는가?','아니며함수타입연결검사다','같은인자면모든메모리효과가자동으로같다','타입일치와실행의의미는다릅니다.동시성 계약은각 구현과공식문서를대조합니다.'),('이검사에서포인터의const/volatile도계약검토대상인가?','예이며signature를정확히 확인한다','함수 이름이같으면타입 수식은무관하다','반환과인자타입이일치해야합니다.포인터수식은읽기·쓰기및최적화경계와관련됩니다.')],
  [('fixture','실제generic함수와원본arch/non-instrumentedaliases의타입 검사를compile했습니다.'),('한계','fixture가선택하지않은architecture의prototype까지전부빌드한증거는아닙니다.')])
 lesson('assign_bit와__assign_bit·진리값에따라set또는clear','assign_bit',
  '한 bit에참·거짓을대입하는편의macro와atomic/non-atomic차이를배웁니다.',
  'assign_bit는value가참이면set_bit,거짓이면clear_bit를선택합니다. __assign_bit는각각__set_bit와__clear_bit를선택합니다.여기서value는숫자1만허용하는것이아니라C진리값조건입니다.두API의동시성 계약은서로다릅니다.atomic갱신이필요한상황에__형을무조건사용하면안됩니다.',
  'bitmap위치에bool조건을저장할때유효nr와bitmap을전달합니다.동시 writer의유무와상위 잠금 규칙을확인해맞는계열을사용합니다.하나의bit의원자성이다른 데이터공개까지자동제공한다고가정하지 않습니다.',
  '두삼항macro의value조건과set/clear대상을읽으세요.',
  [('__assign_bit가선택하는갱신계열은?','__접두의non-atomic갱신이다','항상atomic set_bit만쓴다','원문은__set_bit또는__clear_bit로연결합니다.atomic편의macro와구분합니다.'),('assign_bit의참조건에숫자2를전달하면?','C진리값으로참이라set경로다','1이아니므로무조건clear다','조건은일반삼항의진리값평가입니다.bool의의미와특정숫자일치검사를혼동하지않습니다.')],
  [('검사','native64의bit63 set/clear를실제macro로확인했습니다.atomic함수는fixture의C11강한모델입니다.'),('ordering','set/clear의원자적 갱신과다른memory필드의공개ordering을분리해읽습니다.')])
 lesson('포인터bit태그·객체주소가아닌포인터 변수의표현','__ptr_set_bit',
  '포인터값에정보bit를넣는kernel기술과접근·ABI전제를배웁니다.',
  '__ptr_set/clear/test_bit는addr가가리키는포인터 변수에typecheck_pointer를적용하고unsigned long*로표현을접근합니다.포인터가가리키는객체의메모리 내용을바꾸는것이아닙니다.정렬로비어있는bit를태그로쓸수있지만태그를담은값을그대로일반객체주소로역참조하면안됩니다.이계열의갱신은non-atomic이며nr범위도호출자전제입니다.',
  'kernel의정해진포인터표현·정렬·태그규칙을확인합니다.태그를제거한실제 주소로만객체에접근합니다.일반ISO C나모든ABI의portable tagging이라고확대하지 않습니다.포인터 변수의주소를전달합니다.',
  'typecheck_pointer(*(addr))와unsigned long* cast·세bit API를읽으세요.',
  [('__ptr_set_bit의addr는무엇의주소인가?','태그를넣을포인터 변수의주소다','항상포인터가가리키는객체의첫byte다','원문은포인터 변수의표현을unsigned long*로접근합니다.객체데이터수정과다릅니다.'),('태그가남은포인터를그대로역참조해도되는가?','아니며태그규칙에맞게실제 주소를복원해야한다','태그는CPU가모든ABI에서자동무시한다','태그의허용bit와복원조건은상위 계약입니다.임의태그값의역참조안전성을이helper가제공하지않습니다.')],
  [('검사','정렬된할당포인터의낮은 두 bit를set/test/clear해원래 주소로복원한뒤free했습니다.태그가남은주소는역참조하지않았습니다.'),('compiler','fixture는native long64와 -fno-strict-aliasing문맥입니다.포인터표현별칭을모든C문맥의안전성증명으로계산하지않습니다.')])
 lesson('set_mask_bits·CAS실패시새old로다시계산','set_mask_bits',
  '여러bit를한 번에바꾸는compare-exchange재시도 loop의원리를배웁니다.',
  'set_mask_bits는mask와bits를지역 변수에받고old를READ_ONCE로읽습니다. new=(old&~mask)|bits를계산한뒤try_cmpxchg합니다.실패하면expected인old에현재 값이들어오므로new를다시계산합니다.성공할때까지재시도해다른writer가바꾼mask밖bit를보존합니다.반환값은성공 시에교체한이전old입니다.',
  '유효한stable객체포인터와지원되는원자적타입을준비합니다.마스크로지울구간과넣을bit를정의합니다.반환 old가최초READ_ONCE값이아닐수있음을확인합니다.재시도callback처럼외부부작용을반복계산안에넣지않습니다.',
  'READ_ONCE→new계산→expected갱신CAS→loop→old반환을읽으세요.',
  [('try_cmpxchg실패후같은new를무조건재사용하는가?','아니며갱신된old로new를다시계산한다','최초new를성공할때까지그대로쓴다','새current값의mask밖bit를보존하려면재계산이필요합니다.실패시expected갱신계약과연결됩니다.'),('성공한set_mask_bits의반환값은?','그성공 시에교체한old값이다','항상새로쓴new값이다','원문은old__를반환합니다.실패후old가바뀔수있으므로최초 읽은값과도구분합니다.')],
  [('재시도 검사','최초0읽기뒤경쟁자가0x100을공개하도록주입해반환 old0x100,최종0x101을확인했습니다.'),('동시 실행','C11seq-cst CAS모델에서4writer가각8bit필드를1만번갱신해총4만성공갱신과필드 밖보존을확인했습니다.전체LKMM증명은아닙니다.')])
 lesson('set_mask_bits의bits인자·mask밖bit도OR될수있다','set_mask_bits',
  'helper가자동으로새bits를mask안에제한하는지원본식을확인합니다.',
  '원문의new식은(old&~mask)|bits입니다. bits&mask를먼저수행하지않으므로bits에mask밖1이있으면그위치도켜집니다. old0x55,mask0x0f,bits0x80이면new0xd0입니다.필드 밖을완전히유지하려는호출자는bits가mask부분집합인지확인해야합니다.함수 이름만으로입력범위가제한된다고추측하지 않습니다.',
  '필드를교체하려면bits&~mask가0인표현을만듭니다.FIELD_PREP등으로값위치를맞추고runtime범위를검사합니다.의도적으로다른 bit도설정하려면원문의실제OR계약을명시합니다.',
  '(old&~mask)|bits와없어져있는bits&mask조건을읽으세요.',
  [('old0x55,mask0x0f,bits0x80의새값은?','0xd0이다','bits를자동제한한0x50이다','mask구간을지워0x50을남긴뒤0x80을OR합니다.bits는자동으로mask안에제한되지않습니다.'),('mask밖bit를전부유지하려면bits에필요한조건은?','mask밖1bit가없어야한다','bits는아무값이어도자동으로범위를잘라준다','원문은bits전체를OR합니다.호출자가필요한부분집합조건과숫자범위를지켜야 합니다.')],
  [('검사','mask밖bits의실제결과와성공 반환 old를fixture에서별도로확인했습니다.'),('범위','이조건은값 계산의계약입니다.포인터유효성·지원 CAS 폭·상위동기화전제는별도로확인합니다.')])
 lesson('bit_clear_unless·testbit가있으면clear하지않기','bit_clear_unless',
  '조건부CASloop가검사조건과재시도를어떻게결합하는지배웁니다.',
  'bit_clear_unless는old&test가참이면clear없이loop를끝냅니다.아니면old&~clear를CAS합니다.실패후현재old로돌아와test도다시검사합니다.경쟁자가testbit를켰다면다음 반복에서취소됩니다.반환은!(old&test)이며이미clearbit가0이어도조건이없으면true일수있습니다.반환true는이전clearbit가1이었다는뜻이아닙니다.',
  '상태bit가작업을금지하는경우에사용하고clear/test구간을정합니다.결과를조건통과의의미로해석합니다.다른객체의수명 보호나lock획득까지이bool이제공한다고확대하지 않습니다.',
  'test조건·break·clear계산·expected재시도·반환조건을읽으세요.',
  [('CAS실패후경쟁자가testbit를켰다면?','새old에서조건을재검사해clear를취소할수있다','최초조건이거짓이면반드시계속clear한다','실패는current값을old로갱신합니다.loop에서test조건도다시평가하므로새 상태를반영합니다.'),('반환true가이전clearbit가반드시1이었음을뜻하는가?','아니며금지test조건이없었다는결과다','true면언제나1에서0으로변경했다','원문의반환은!(old&test)입니다.clearbit가이미0인사례도true가될 수 있습니다.')],
  [('검사','성공·이미clear·test존재취소·CAS실패후test추가취소네사례를확인했습니다.'),('모델','READ_ONCE와CAS는명시한C11모델입니다.실제kernel전체메모리모델이나모든architecture구현을검증한것은아닙니다.')])
 lesson('bitops사용경계·값연산 일반 메모리 원자적 갱신을구분','__assign_bit',
  '한헤더안의여러기술을실제작업의계약에맞게고르는연습을합니다.',
  'rotate/sign/order는값 계산이고__set/clear/change와__assign은non-atomic bitmap수정입니다.test_bit는읽기이며test_bit_acquire는acquire계약입니다.set_mask_bits와bit_clear_unless는CAS재시도입니다.태그helper는포인터 변수표현을다룹니다.헤더의__KERNEL__조건과ifndef선택은다른 구현이정의된경우generic macro를대체하지않도록합니다.',
  '먼저값 계산인지객체수정인지정하고,폭·주소·동시성·ordering·상위수명조건을확인합니다.같은bit계열이름만보고모든helper가atomic이거나모두MMIO에적합하다고판단하지 않습니다.',
  '전체선언·include·alias·값함수·포인터macro·kernel조건부CAS정의를묶어읽으세요.',
  [('rotate값함수가bitmap메모리를자동으로수정하는가?','아니며입력값의변환결과를반환한다','같은bitops헤더면모든함수가메모리를수정한다','값연산과메모리갱신의역할을구분합니다.인자와본문의대입대상을확인해야합니다.'),('모든bitops가장치MMIO에직접사용가능한가?','아니며각접근API와장치규약이필요하다','일반 메모리와MMIO의계약은항상 같다','헤더의일반 메모리연산은장치의접근폭·순서·posted write계약을자동제공하지않습니다.')],
  [('전체 파일','저장macro,software선언,상수선택,prototype 검사,회전·부호·order·rank,assign·태그·CAS와guard전체를읽고작성했습니다.'),('검사','현재native64 fixture는3,780,023개기록 검사와scalar/function/nonpointer compile 거절을통과했습니다.원본일반helper와명시한모델의범위를기록합니다.')])
